#pragma once
// Round 13 owner decision 7: "Gift/static encounters require proper source-backed data before v1.0
// acceptance. Markers alone are provisional."
//
// The gift / static / in-game trade / fossil / prize / roaming encounters of Crystal, Ruby,
// Sapphire, Emerald, FireRed, LeafGreen, Diamond, Pearl, Platinum, HeartGold, SoulSilver, Black,
// White, Black 2 and White 2, generated by tools/gen_gift_static_encounters.py from PKHeX's
// encounter tables (pinned commit) and cross-checked against the pret decompilations (every
// Crystal row; Gen III spot checks). Sources, hashes and per-game coverage / gaps:
// docs/data/gift-static-encounter-sources.json, docs/data/GIFT_STATIC_ENCOUNTER_COVERAGE.md.
//
// Each row is the record's exact NATIVE met location and met level range:
//   - an in-game trade is met at the game's own trade location (Crystal LANDMARK_GIFT 0x7E,
//     Gen III 254, Gen IV 2001, Gen V 30002; PKHeX Locations.LinkTrade*NPC);
//   - a roamer has one row per route it can be met on (PKHeX roamer route sets);
//   - an egg gift is met where it hatched, so its rows are data only, never a Met Location row
//     (metLocationRow() is false; the egg / breeding histories are a separate lane).
// Event DISTRIBUTIONS (Mystery Gift / Wonder Card, Gen IV 3000+ / Gen V 40000+ locations) are not
// here: there is no data, and the editor keeps them unverified. An "event" row here is an in-game
// static encounter the game's own script holds (Navel Rock Lugia, Ilex Forest Celebi, Liberty
// Garden Victini ...); its fateful flag is recorded where the game sets it.
#include "Integration/Encounter/EncounterGuardrails.h"

#include <cstdint>
#include <string>
#include <string_view>
#include <vector>

namespace PokeVault::Integration::GiftStaticEncounters {

enum class Kind : uint8_t { Gift, Prize, Fossil, Static, Roaming, Trade, EventStatic, EggGift, Swarm };

// Row flags.
inline constexpr uint8_t kFateful = 1;               // the game sets the fateful-encounter flag
inline constexpr uint8_t kNsPokemon = 2;             // Black 2 / White 2 N's Pokémon
inline constexpr uint8_t kCaughtLevelUnrecorded = 4; // Crystal SetGiftMonCaughtData: level 0, time 0

// Owner decision (Nov 2): "Do not label a Pokémon's complete acquisition history Verified simply
// because its encounter exists in the game's scripts." Three things are kept apart:
//  1. the encounter itself -- script-backed (every row here; its provenance is `confidence`);
//  2. the access prerequisite -- a ticket / key item distribution, an event-distributed Pokémon in
//     the party, or a Pokémon only another game provides (`prereq`);
//  3. when that prerequisite cannot be known from a save, the acquisition evidence is INCOMPLETE:
//     the row is listed as "encounter in the game" but never as a verified encounter, and the
//     editor / Review note says Incomplete (incompleteNote()).
enum class Prerequisite : uint8_t { None, TicketOrItem, EventPokemon, OtherGame };
// Source confidence of a row: matched to a pret map script (every Crystal static / gift / prize /
// trade row), one of the Gen III pret spot checks, or PKHeX alone (every Gen IV / V row and the
// other Gen III / Crystal rows). A single-source row is never called independently verified.
enum class Confidence : uint8_t { PretChecked, PretSpotChecked, SingleSource };

struct Row {
    std::string_view game;
    uint16_t species;
    uint16_t location;
    uint8_t minLevel;
    uint8_t maxLevel;
    Kind kind;
    uint8_t flags;
    uint8_t form;
    uint16_t eggLocation;
    Prerequisite prereq;
    Confidence confidence;
};

struct PrerequisiteReason {
    std::string_view game;
    uint16_t species;
    uint16_t location;
    std::string_view reason;
};

#include "Integration/Encounter/GiftStaticEncountersData.inc"

constexpr const char* kindLabel(Kind kind) noexcept {
    switch (kind) {
        case Kind::Gift: return "gift";
        case Kind::Prize: return "prize";
        case Kind::Fossil: return "fossil";
        case Kind::Static: return "static";
        case Kind::Roaming: return "roaming";
        case Kind::Trade: return "trade";
        case Kind::EventStatic: return "event";
        case Kind::EggGift: return "egg gift";
        case Kind::Swarm: return "swarm";
    }
    return "encounter";
}

constexpr EncounterGuardrails::Method method(Kind kind) noexcept {
    using M = EncounterGuardrails::Method;
    switch (kind) {
        case Kind::Gift: return M::Gift;
        case Kind::Prize: return M::Prize;
        case Kind::Fossil: return M::Fossil;
        case Kind::Static: return M::Static;
        case Kind::Roaming: return M::Roaming;
        case Kind::Trade: return M::Trade;
        case Kind::EventStatic: return M::Event;
        case Kind::EggGift: return M::Egg;
        case Kind::Swarm: return M::Swarm;
    }
    return M::Static;
}

constexpr const char* prerequisiteLabel(Prerequisite prereq) noexcept {
    switch (prereq) {
        case Prerequisite::None: return "";
        case Prerequisite::TicketOrItem: return "ticket / distribution";
        case Prerequisite::EventPokemon: return "event Pokémon";
        case Prerequisite::OtherGame: return "Pokémon from another game";
    }
    return "prerequisite";
}

constexpr const char* confidenceLabel(Confidence confidence) noexcept {
    switch (confidence) {
        case Confidence::PretChecked: return "PKHeX + pret cross-checked";
        case Confidence::PretSpotChecked: return "PKHeX + pret spot-checked";
        case Confidence::SingleSource: return "single source (PKHeX)";
    }
    return "unknown source";
}

// The encounter exists in the game, and no access prerequisite stands between it and a save.
constexpr bool fullyVerifiable(const Row& row) noexcept { return row.prereq == Prerequisite::None; }

constexpr std::string_view prerequisiteReason(const Row& row) noexcept {
    for (const auto& r : kPrerequisiteReasons)
        if (r.game == row.game && r.species == row.species && r.location == row.location) return r.reason;
    return {};
}

// Short row suffix (fits the 620 / 640 px pickers) for an encounter whose access is unknown.
inline constexpr const char* kAccessUnverified = "access unverified";

// The editor / Review line for an Incomplete acquisition: the encounter is in the game, the
// prerequisite is not verifiable from the save.
inline std::string incompleteNote(const Row& row) {
    return std::string("Incomplete: encounter in game script; ") + prerequisiteLabel(row.prereq) +
           " not verifiable from the save";
}

// The provenance line for a verified data row that has only one source ("" otherwise).
inline std::string singleSourceNote(const Row& row) {
    if (row.confidence != Confidence::SingleSource) return {};
    return std::string("Encounter data: ") + confidenceLabel(row.confidence);
}

// A row the Met Location pickers offer (an egg gift is met where it hatched).
constexpr bool metLocationRow(const Row& row) noexcept { return row.kind != Kind::EggGift; }

// The games this table covers (every Gen II-V game with an editor Met Location picker).
constexpr bool covers(std::string_view game) noexcept {
    for (const auto& row : kRows)
        if (row.game == game) return true;
    return false;
}

inline std::vector<const Row*> rowsFor(std::string_view game, uint16_t species) {
    std::vector<const Row*> out;
    for (const auto& row : kRows)
        if (row.game == game && row.species == species) out.push_back(&row);
    return out;
}

constexpr EncounterGuardrails::EncounterTemplate templateOf(const Row& row) noexcept {
    return {row.game, row.species, row.location, row.minLevel, row.maxLevel, method(row.kind), 0};
}

// The Met Location templates of `species` in `game`: the wild / fishing / headbutt / egg templates
// (EncounterGuardrails) plus this table's gift / static / trade / fossil / prize / roaming / event /
// swarm rows, which REPLACE the older hand-carried Static / Gift / Event rows for the games this
// table covers (they are all in it, now with their kind, fixed level and pret cross-check).
inline std::vector<EncounterGuardrails::EncounterTemplate> metTemplates(std::string_view game, uint16_t species) {
    namespace E = EncounterGuardrails;
    std::vector<E::EncounterTemplate> out;
    const bool covered = covers(game);
    for (const auto& encounter : E::forGameSpecies(game, species)) {
        if (covered && (encounter.method == E::Method::Static || encounter.method == E::Method::Gift ||
                        encounter.method == E::Method::Event))
            continue;
        out.push_back(encounter);
    }
    for (const auto* row : rowsFor(game, species))
        if (metLocationRow(*row)) out.push_back(templateOf(*row));
    return E::deduplicateExactEncounterTemplates(out);
}

// The table row a Met Location template came from, or nullptr for a wild / egg template.
inline const Row* rowOf(const EncounterGuardrails::EncounterTemplate& encounter) noexcept {
    for (const auto& row : kRows)
        if (row.game == encounter.sourceGameId && row.species == encounter.species &&
            row.location == encounter.location && row.minLevel == encounter.minLevel &&
            row.maxLevel == encounter.maxLevel && method(row.kind) == encounter.method && metLocationRow(row))
            return &row;
    return nullptr;
}

} // namespace PokeVault::Integration::GiftStaticEncounters
